-- Search suggestions generated by the autocomplete engine
CREATE TABLE search_suggestions
(
    Id               INTEGER NOT NULL PRIMARY KEY,
    QueryText        TEXT,
    SuggestedTerm    TEXT,
    RelevanceScore   REAL,
    CreatedAt        DATETIME,
    UpdatedAt        DATETIME,
    UserAgentHash    TEXT,
    RegionCode       TEXT,
    DeviceType       TEXT,
    IsPromoted       INTEGER,
    SourceAlgorithm  TEXT,
    LanguageCode     TEXT,
    SessionId        INTEGER,
    ClickCount       INTEGER,
    ImpressionCount  INTEGER,
    AvgDwellTime     REAL,
    Category         TEXT,
    ConfidenceLevel  REAL,
    IsActive         INTEGER,
    Notes            TEXT
);

