-- API rate limit rules applied to endpoints
CREATE TABLE api_rate_limit_rules
(
    Id                     INTEGER NOT NULL PRIMARY KEY,
    Endpoint               TEXT,
    HttpMethod             TEXT,
    LimitCount             INTEGER,
    WindowSeconds          INTEGER,
    BurstCapacity          INTEGER,
    IsEnabled              INTEGER,
    CreatedBy              INTEGER,
    CreatedAt              DATETIME,
    UpdatedBy              INTEGER,
    UpdatedAt              DATETIME,
    Description            TEXT,
    ViolationPenaltySeconds INTEGER,
    MaxConcurrentRequests  INTEGER,
    AppliesToIPRange       TEXT,
    AppliesToUserRole      TEXT,
    GeoRestriction         TEXT,
    IsPermanent            INTEGER,
    LastChecked            DATETIME,
    RuleVersion            INTEGER
);

