    ErrorCode        TEXT,
    ErrorMessage     TEXT,
    RequestId        TEXT,
    Timestamp        DATETIME,
    ClientIp         TEXT,
    UserAgent        TEXT,
    RetryCount       INTEGER,
    BackoffSeconds   REAL,
    CorrelationId    TEXT,
    StackTrace       TEXT,
    AlertSent        INTEGER,
    Severity         TEXT,
    AffectedRegion   TEXT,
    PayloadSnippet   TEXT,
    ResponseTimeMs   REAL,
    IsTransient      INTEGER
);

